INSERT INTO company_translations (company_id, lang_code, name, slug, description)
SELECT c.company_id, 'vi', t.name, t.slug, NULL
FROM companies c
JOIN (
    SELECT 'VN000000BIC1' AS id_no, 'Tổng Công ty Bảo hiểm Ngân hàng Đầu tư và Phát triển Việt Nam' AS name, 'tổng-công-ty-bảo-hiểm-ngân-hàng-đầu-tư-và-phát-triển-việt-nam' AS slug UNION ALL SELECT 'VN000000BID9' AS id_no, 'Ngân hàng Thương mại Cổ phần Đầu tư và Phát triển Việt Nam' AS name, 'ngân-hàng-thương-mại-cổ-phần-đầu-tư-và-phát-triển-việt-nam' AS slug UNION ALL SELECT 'VN000000BKG8 ' AS id_no, 'Công ty Cổ phần Đầu tư BKG Việt Nam' AS name, 'công-ty-cổ-phần-đầu-tư-bkg-việt-nam' AS slug UNION ALL SELECT 'VN000000BMC3' AS id_no, 'Công ty Cổ phần Khoáng sản Bình Định' AS name, 'công-ty-cổ-phần-khoáng-sản-bình-định' AS slug UNION ALL SELECT 'VN000000BMI0' AS id_no, 'Tổng Công ty Cổ phần Bảo Minh' AS name, 'tổng-công-ty-cổ-phần-bảo-minh' AS slug UNION ALL SELECT 'VN000000BMP5' AS id_no, 'Công ty Cổ phần Nhựa Bình Minh' AS name, 'công-ty-cổ-phần-nhựa-bình-minh' AS slug UNION ALL SELECT 'VN000000BRC2' AS id_no, 'Công ty Cổ phần Cao su Bến Thành' AS name, 'công-ty-cổ-phần-cao-su-bến-thành' AS slug UNION ALL SELECT 'VN000000BSI7' AS id_no, 'Công ty Cổ phần Chứng khoán BIDV' AS name, 'công-ty-cổ-phần-chứng-khoán-bidv' AS slug UNION ALL SELECT 'VN000000BSR8' AS id_no, 'Công ty Cổ phần Lọc hóa dầu Bình Sơn' AS name, 'công-ty-cổ-phần-lọc-hóa-dầu-bình-sơn' AS slug UNION ALL SELECT 'VN000000BTP0' AS id_no, 'Công ty Cổ phần Nhiệt điện Bà Rịa' AS name, 'công-ty-cổ-phần-nhiệt-điện-bà-rịa' AS slug UNION ALL SELECT 'VN000000BTT2' AS id_no, 'Công ty Cổ phần Thương mại – Dịch vụ Bến Thành' AS name, 'công-ty-cổ-phần-thương-mại-–-dịch-vụ-bến-thành' AS slug UNION ALL SELECT 'VN000000BVH3' AS id_no, 'Tập đoàn Bảo Việt' AS name, 'tập-đoàn-bảo-việt' AS slug UNION ALL SELECT 'VN000000BWE8' AS id_no, 'Công ty Cổ phần - Tổng Công ty Nước – Môi trường Bình Dương' AS name, 'công-ty-cổ-phần---tổng-công-ty-nước-–-môi-trường-bình-dương' AS slug UNION ALL SELECT 'VN000000C325' AS id_no, 'Công ty Cổ phần Đầu tư và Xây dựng 3-2' AS name, 'công-ty-cổ-phần-đầu-tư-và-xây-dựng-3-2' AS slug UNION ALL SELECT 'VN000000C473' AS id_no, 'Công ty Cổ phần Xây dựng 47' AS name, 'công-ty-cổ-phần-xây-dựng-47' AS slug UNION ALL SELECT 'VN000000CCC2' AS id_no, 'Công ty Cổ phần Xây dựng CDC' AS name, 'công-ty-cổ-phần-xây-dựng-cdc' AS slug UNION ALL SELECT 'VN000000CCI9' AS id_no, 'Công ty Cổ phần Đầu tư Phát triển Công nghiệp Thương mại Củ Chi' AS name, 'công-ty-cổ-phần-đầu-tư-phát-triển-công-nghiệp-thương-mại-củ-chi' AS slug UNION ALL SELECT 'VN000000CCL3' AS id_no, 'Công ty Cổ phần Đầu tư và Phát triển Đô thị Dầu khí Cửu Long' AS name, 'công-ty-cổ-phần-đầu-tư-và-phát-triển-đô-thị-dầu-khí-cửu-long' AS slug UNION ALL SELECT 'VN000000CDC0' AS id_no, 'Công ty Cổ phần Chương Dương' AS name, 'công-ty-cổ-phần-chương-dương' AS slug UNION ALL SELECT 'VN000000CHP3' AS id_no, 'Công ty Cổ phần Thủy điện Miền Trung' AS name, 'công-ty-cổ-phần-thủy-điện-miền-trung' AS slug UNION ALL SELECT 'VN000000CIG0' AS id_no, 'Công ty Cổ phần COMA18' AS name, 'công-ty-cổ-phần-coma18' AS slug UNION ALL SELECT 'VN000000CII6' AS id_no, 'Công ty Cổ phần Đầu tư Hạ tầng Kỹ thuật TP.HCM' AS name, 'công-ty-cổ-phần-đầu-tư-hạ-tầng-kỹ-thuật-tp.hcm' AS slug UNION ALL SELECT 'VN000000CKG6' AS id_no, 'Công ty Cổ phần Tập đoàn CIC' AS name, 'công-ty-cổ-phần-tập-đoàn-cic' AS slug UNION ALL SELECT 'VN000000CLC3' AS id_no, 'Công ty Cổ phần Cát Lợi' AS name, 'công-ty-cổ-phần-cát-lợi' AS slug UNION ALL SELECT 'VN000000CLL4' AS id_no, 'Công ty Cổ phần Cảng Cát Lái' AS name, 'công-ty-cổ-phần-cảng-cát-lái' AS slug UNION ALL SELECT 'VN000000CLW1' AS id_no, 'Công ty Cổ phần Cấp nước Chợ Lớn' AS name, 'công-ty-cổ-phần-cấp-nước-chợ-lớn' AS slug UNION ALL SELECT 'VN000000CMG2' AS id_no, 'Công ty Cổ phần Tập đoàn Công nghệ CMC' AS name, 'công-ty-cổ-phần-tập-đoàn-công-nghệ-cmc' AS slug UNION ALL SELECT 'VN000000CMV1' AS id_no, 'Công ty Cổ phần Thương nghiệp Cà Mau' AS name, 'công-ty-cổ-phần-thương-nghiệp-cà-mau' AS slug UNION ALL SELECT 'VN000000CMX7' AS id_no, 'Công ty Cổ phần Camimex Group' AS name, 'công-ty-cổ-phần-camimex-group' AS slug UNION ALL SELECT 'VN000000CNG0' AS id_no, 'Công ty Cổ phần CNG Việt Nam' AS name, 'công-ty-cổ-phần-cng-việt-nam' AS slug
) AS t ON c.id_no = t.id_no
ON DUPLICATE KEY UPDATE
    name = t.name,
    slug = t.slug;
COMMIT;

START TRANSACTION;

