INSERT INTO company_translations (company_id, lang_code, name, slug, description)
SELECT c.company_id, 'vi', t.name, t.slug, NULL
FROM companies c
JOIN (
    SELECT 'VN000000COM6' AS id_no, 'Công ty Cổ phần Vật tư - Xăng dầu' AS name, 'công-ty-cổ-phần-vật-tư---xăng-dầu' AS slug UNION ALL SELECT 'VN000000CRC0' AS id_no, 'Công ty Cổ phần Create Capital Việt Nam' AS name, 'công-ty-cổ-phần-create-capital-việt-nam' AS slug UNION ALL SELECT 'VN000000CRE6' AS id_no, 'Công ty Cổ phần Bất động sản Thế Kỷ' AS name, 'công-ty-cổ-phần-bất-động-sản-thế-kỷ' AS slug UNION ALL SELECT 'VN000000CRV0' AS id_no, 'Công ty Cổ phần Tập đoàn Bất động sản CRV' AS name, 'công-ty-cổ-phần-tập-đoàn-bất-động-sản-crv' AS slug UNION ALL SELECT 'VN000000CSM7' AS id_no, 'Công ty Cổ phần Công nghiệp Cao su Miền Nam' AS name, 'công-ty-cổ-phần-công-nghiệp-cao-su-miền-nam' AS slug UNION ALL SELECT 'VN000000CSV8' AS id_no, 'Công ty Cổ phần Hóa chất cơ bản miền Nam' AS name, 'công-ty-cổ-phần-hóa-chất-cơ-bản-miền-nam' AS slug UNION ALL SELECT 'VN000000CTD4' AS id_no, 'Công ty Cổ phần Xây dựng COTECCONS' AS name, 'công-ty-cổ-phần-xây-dựng-coteccons' AS slug UNION ALL SELECT 'VN000000CTF9' AS id_no, 'Công ty Cổ phần City Auto' AS name, 'công-ty-cổ-phần-city-auto' AS slug UNION ALL SELECT 'VN000000CTG7' AS id_no, 'Ngân hàng Thương mại Cổ phần Công Thương Việt Nam' AS name, 'ngân-hàng-thương-mại-cổ-phần-công-thương-việt-nam' AS slug UNION ALL SELECT 'VN000000CTI3' AS id_no, 'Công ty Cổ phần Đầu tư Phát triển Cường Thuận IDICO' AS name, 'công-ty-cổ-phần-đầu-tư-phát-triển-cường-thuận-idico' AS slug UNION ALL SELECT 'VN000000CTR4' AS id_no, 'Tổng Công ty Cổ phần Công trình Viettel' AS name, 'tổng-công-ty-cổ-phần-công-trình-viettel' AS slug UNION ALL SELECT 'VN000000CTS2' AS id_no, 'Công ty Cổ phần Chứng khoán VietinBank' AS name, 'công-ty-cổ-phần-chứng-khoán-vietinbank' AS slug UNION ALL SELECT 'VN000000CVT6' AS id_no, 'Công ty Cổ phần CMC' AS name, 'công-ty-cổ-phần-cmc' AS slug UNION ALL SELECT 'VN000000D2D0' AS id_no, 'Công ty Cổ phần Phát triển Đô thị Công nghiệp số 2' AS name, 'công-ty-cổ-phần-phát-triển-đô-thị-công-nghiệp-số-2' AS slug UNION ALL SELECT 'VN0000