UNION ALL SELECT 'VN000000DLG2' AS id_no, 'Công ty Cổ phần Tập đoàn Đức Long Gia Lai' AS name, 'công-ty-cổ-phần-tập-đoàn-đức-long-gia-lai' AS slug
) AS t ON c.id_no = t.id_no
ON DUPLICATE KEY UPDATE
    name = t.name,
    slug = t.slug;
COMMIT;

