INSERT INTO company_translations (company_id, lang_code, name, slug, description)
SELECT c.company_id, 'vi', t.name, t.slug, NULL
FROM companies c
JOIN (
    SELECT 'VN000000DMC9' AS id_no, 'Công ty Cổ phần Xuất nhập khẩu Y tế DOMESCO' AS name, 'công-ty-cổ-phần-xuất-nhập-khẩu-y-tế-domesco' AS slug UNION ALL SELECT 'VN000000DPG3' AS id_no, 'Công ty Cổ phần Tập đoàn Đạt Phương' AS name, 'công-ty-cổ-phần-tập-đoàn-đạt-phương' AS slug UNION ALL SELECT 'VN000000DPM1' AS id_no, 'Tổng Công ty Phân bón và Hóa chất Dầu khí - Công ty Cổ phần' AS name, 'tổng-công-ty-phân-bón-và-hóa-chất-dầu-khí---công-ty-cổ-phần' AS slug UNION ALL SELECT 'VN000000DPR0' AS id_no, 'Công ty Cổ phần Cao su Đồng Phú' AS name, 'công-ty-cổ-phần-cao-su-đồng-phú' AS slug UNION ALL SELECT 'VN000000DQC0' AS id_no, 'Công ty Cổ phần Tập đoàn Điện Quang' AS name, 'công-ty-cổ-phần-tập-đoàn-điện-quang' AS slug UNION ALL SELECT 'VN000000DRC8' AS id_no, 'Công ty Cổ phần Cao su Đà Nẵng' AS name, 'công-ty-cổ-phần-cao-su-đà-nẵng' AS slug UNION ALL SELECT 'VN000000DRH7' AS id_no, 'Công ty Cổ phần DRH Holdings' AS name, 'công-ty-cổ-phần-drh-holdings' AS slug UNION ALL SELECT 'VN000000DRL9' AS id_no, 'Công ty Cổ phần Thủy điện - Điện lực 3' AS name, 'công-ty-cổ-phần-thủy-điện---điện-lực-3' AS slug UNION ALL SELECT 'VN000000DSC6' AS id_no, 'Công ty Cổ phần Chứng khoán DSC' AS name, 'công-ty-cổ-phần-chứng-khoán-dsc' AS slug UNION ALL SELECT 'VN000000DSE2' AS id_no, 'Công ty Cổ phần Chứng khoán DNSE' AS name, 'công-ty-cổ-phần-chứng-khoán-dnse' AS slug UNION ALL SELECT 'VN000000DSN3' AS id_no, 'Công ty Cổ phần Công viên nước Đầm Sen' AS name, 'công-ty-cổ-phần-công-viên-nước-đầm-sen' AS slug UNION ALL SELECT 'VN000000DTA8' AS id_no, 'Công ty Cổ phần Đệ Tam' AS name, 'công-ty-cổ-phần-đệ-tam' AS slug UNION ALL SELECT 'VN000000DTL5' AS id_no, 'Công ty Cổ phần Đại Thiên Lộc' AS name, 'công-ty-cổ-phần-đại-thiên-lộc' AS slug UNION ALL SELECT 'VN000000DTT8' AS id_no, 'Công ty Cổ phần Kỹ nghệ Đô Thành' AS name, 'công-ty-cổ-phần-kỹ-nghệ-đô-thành' AS slug UNION ALL SELECT 'VN000000DVP2' AS id_no, 'Công ty Cổ phần Đầu tư và Phát triển Cảng Đình Vũ' AS name, 'công-ty-cổ-phần-đầu-tư-và-