ổ-phần-thực-phẩm-sao-ta' AS slug UNION ALL SELECT 'VN000000FPT1' AS id_no, 'Công ty Cổ phần FPT' AS name, 'công-ty-cổ-phần-fpt' AS slug
) AS t ON c.id_no = t.id_no
ON DUPLICATE KEY UPDATE
