INSERT INTO company_translations (company_id, lang_code, name, slug, description)
SELECT c.company_id, 'vi', t.name, t.slug, NULL
FROM companies c
JOIN (
    SELECT 'VN000000FRT7' AS id_no, 'Công ty Cổ phần Bán lẻ Kỹ thuật số FPT' AS name, 'công-ty-cổ-phần-bán-lẻ-kỹ-thuật-số-fpt' AS slug UNION ALL SELECT 'VN000000FTS5' AS id_no, 'Công ty Cổ phần Chứng khoán FPT' AS name, 'công-ty-cổ-phần-chứng-khoán-fpt' AS slug UNION ALL SELECT 'VN000000GAS3' AS id_no, 'Tổng Công ty Khí Việt Nam - Công ty Cổ phần' AS name, 'tổng-công-ty-khí-việt-nam---công-ty-cổ-phần' AS slug UNION ALL SELECT 'VN000000GDT5' AS id_no, 'Công ty Cổ phần Chế biến Gỗ Đức Thành' AS name, 'công-ty-cổ-phần-chế-biến-gỗ-đức-thành' AS slug UNION ALL SELECT 'VN000000GEE5' AS id_no, 'Công ty Cổ phần Điện lực Gelex' AS name, 'công-ty-cổ-phần-điện-lực-gelex' AS slug UNION ALL SELECT 'VN000000GEG0' AS id_no, 'Công ty Cổ phần Điện Gia Lai' AS name, 'công-ty-cổ-phần-điện-gia-lai' AS slug UNION ALL SELECT 'VN000000GEL0' AS id_no, 'Công ty Cổ phần Hạ tầng GELEX' AS name, 'công-ty-cổ-phần-hạ-tầng-gelex' AS slug UNION ALL SELECT 'VN000000GEX5' AS id_no, 'Công ty Cổ phần Tập đoàn GELEX' AS name, 'công-ty-cổ-phần-tập-đoàn-gelex' AS slug UNION ALL SELECT 'VN000000GHC2' AS id_no, 'Công ty Cổ phần Thủy điện Gia Lai' AS name, 'công-ty-cổ-phần-thủy-điện-gia-lai' AS slug UNION ALL SELECT 'VN000000GIL1' AS id_no, 'Công ty Cổ phần Sản xuất Kinh doanh Xuất nhập khẩu Bình Thạnh' AS name, 'công-ty-cổ-phần-sản-xuất-kinh-doanh-xuất-nhập-khẩu-bình-thạnh' AS slug UNION ALL SELECT 'VN000000GMD0' AS id_no, 'Công ty Cổ phần GEMADEPT' AS name, 'công-ty-cổ-phần-gemadept' AS slug UNION ALL SELECT 'VN000000GMH1' AS id_no, 'Công ty Cổ phần Minh Hưng Quảng Trị' AS name, 'công-ty-cổ-phần-minh-hưng-quảng-trị' AS slug UNION ALL SELECT 'VN000000GSP1' AS id_no, 'Công ty Cổ phần Vận tải Sản phẩm Khí Quốc tế' AS name, 'công-ty-cổ-phần-vận-tải-sản-phẩm-khí-quốc-tế' AS slug UNION ALL SELECT 'VN000000GTA1' AS id_no, 'Công ty Cổ phần Chế biến Gỗ Thuận An' AS name, 'công-ty-cổ-phần-chế-biến-gỗ-thuận-an' AS slug UNION ALL SELECT 'VN000000GVR1' AS id_no, 'Tập đoàn Công nghiệp Cao su Việt Nam - Công ty Cổ phần' AS name, 'tập-đoàn-công-nghiệp-cao-su-việt-nam---công-ty-cổ-phần' AS slug UNION ALL SELECT 'VN000000HAG6' AS id_no, 'Công ty Cổ phần Hoàng Anh Gia Lai' AS name, 'công-ty-cổ-phần-hoàng-anh-gia-lai' AS slug UNION ALL SELECT 'VN000000HAH4' AS id_no, 'Công ty Cổ phần Vận tải và Xếp dỡ Hải An' AS name, 'công-ty-cổ-phần-vận-tải-và-xếp-dỡ-hải-an' AS slug UNION ALL SELECT 'VN000000HAP7' AS id_no, 'Công ty Cổ phần Tập đoàn HAPACO' AS name, 'công-ty-cổ-phần-tập-đoàn-hapaco' AS slug UNION ALL SELECT 'VN000000HAR3' AS id_no, 'Công ty Cổ phần Đầu tư Thương mại Bất động sản An Dương Thảo Điền' AS name, 'công-ty-cổ-phần-đầu-tư-thương-mại-bất-động-sản-an-dương-thảo-điền' AS slug UNION ALL SELECT 'VN000000HAS1' AS id_no, 'Công ty Cổ phần HACISCO' AS name, 'công-ty-cổ-phần-hacisco' AS slug UNION ALL SELECT 'VN000000HAX1' AS id_no, 'Công ty Cổ phần Dịch vụ Ô tô Hàng Xanh' AS name, 'công-ty-cổ-phần-dịch-vụ-ô-tô-hàng-xanh' AS slug UNION ALL SELECT 'VN000000HCD9' AS id_no, 'Công ty Cổ phần Đầu tư Sản xuất và Thương mại HCD' AS name, 'công-ty-cổ-phần-đầu-tư-sản-xuất-và-thương-mại-hcd' AS slug UNION ALL SELECT 'VN000000HCM0' AS id_no, 'Công ty Cổ phần Chứng khoán Thành phố Hồ Chí Minh' AS name, 'công-ty-cổ-phần-chứng-khoán-thành-phố-hồ-chí-minh' AS slug UNION ALL SELECT 'VN000000HDB1' AS id_no, 'Ngân hàng Thương mại Cổ phần Phát triển Thành phố Hồ Chí Minh' AS name, 'ngân-hàng-thương-mại-cổ-phần-phát-triển-thành-phố-hồ-chí-minh' AS slug UNION ALL SELECT 'VN000000HDC9' AS id_no, 'Công ty Cổ phần Phát triển nhà Bà Rịa – Vũng Tàu' AS name, 'công-ty-cổ-phần-phát-triển-nhà-bà-rịa-–-vũng-tàu' AS slug UNION ALL SELECT 'VN000000HDG0' AS id_no, 'Công ty Cổ phần Tập đoàn Hà Đô' AS name, 'công-ty-cổ-phần-tập-đoàn-hà-đô' AS slug UNION ALL SELECT 'VN000000HHP2' AS id_no, 'Công ty Cổ phần HHP Global' AS name, 'công-ty-cổ-phần-hhp-global' AS slug UNION ALL SELECT 'VN000000HHS6' AS id_no, 'Công ty Cổ phần Đầu tư Dịch vụ Hoàng Huy' AS name, 'công-ty-cổ-phần-đầu-tư-dịch-vụ-hoàng-huy' AS slug UNION ALL SELECT 'VN000000HHV0' AS id_no, 'Công ty Cổ phần Đầu tư Hạ tầng Giao thông Đèo Cả' AS name, 'công-ty-cổ-phần-đầu-tư-hạ-tầng-giao-thông-đèo-cả' AS slug UNION ALL SELECT 'VN000000HID6' AS id_no, 'Công ty Cổ phần Halcom Việt Nam' AS name, 'công-ty-cổ-phần-halcom-việt-nam' AS slug
) AS t ON c.id_no = t.id_no
ON DUPLICATE KEY UPDATE
    name = t.name,
    slug = t.slug;
COMMIT;

