INSERT INTO company_translations (company_id, lang_code, name, slug, description)
SELECT c.company_id, 'vi', t.name, t.slug, NULL
FROM companies c
JOIN (
    SELECT 'VN000000HII5' AS id_no, 'Công ty Cổ phần An Tiến Industries' AS name, 'công-ty-cổ-phần-an-tiến-industries' AS slug UNION ALL SELECT 'VN000000HMC0' AS id_no, 'Công ty Cổ phần Kim khí Thành phố Hồ Chí Minh - Vnsteel' AS name, 'công-ty-cổ-phần-kim-khí-thành-phố-hồ-chí-minh---vnsteel' AS slug UNION ALL SELECT 'VN000000HNA2' AS id_no, 'Công ty Cổ phần Thủy điện Hủa Na' AS name, 'công-ty-cổ-phần-thủy-điện-hủa-na' AS slug UNION ALL SELECT 'VN000000HPA7' AS id_no, 'Công ty Cổ phần Phát triển Nông nghiệp Hòa Phát' AS name, 'công-ty-cổ-phần-phát-triển-nông-nghiệp-hòa-phát' AS slug UNION ALL SELECT 'VN000000HPG4' AS id_no, 'Công ty Cổ phần Tập đoàn Hòa Phát' AS name, 'công-ty-cổ-phần-tập-đoàn-hòa-phát' AS slug UNION ALL SELECT 'VN000000HPX9' AS id_no, 'Công ty Cổ phần Đầu tư Hải Phát' AS name, 'công-ty-cổ-phần-đầu-tư-hải-phát' AS slug UNION ALL SELECT 'VN000000HQC1' AS id_no, 'Công ty Cổ phần Tư vấn – Thương mại – Dịch vụ Địa ốc Hoàng Quân' AS name, 'công-ty-cổ-phần-tư-vấn-–-thương-mại-–-dịch-vụ-địa-ốc-hoàng-quân' AS slug UNION ALL SELECT 'VN000000HRC9' AS id_no, 'Công ty Cổ phần Cao su Hòa Bình' AS name, 'công-ty-cổ-phần-cao-su-hòa-bình' AS slug UNION ALL SELECT 'VN000000HSG8' AS id_no, 'Công ty Cổ phần Tập đoàn Hoa Sen' AS name, 'công-ty-cổ-phần-tập-đoàn-hoa-sen' AS slug UNION ALL SELECT 'VN000000HSL8' AS id_no, 'Công ty Cổ phần Đầu tư Phát triển Thực phẩm Hồng Hà' AS name, 'công-ty-cổ-phần-đầu-tư-phát-triển-thực-phẩm-hồng-hà' AS slug UNION ALL SELECT 'VN000000HT12' AS id_no, 'Công ty Cổ phần Xi măng VICEM Hà Tiên' AS name, 'công-ty-cổ-phần-xi-măng-vicem-hà-tiên' AS slug UNION ALL SELECT 'VN000000HTG6' AS id_no, 'Tổng Công ty Cổ phần Dệt may Hòa Thọ' AS name, 'tổng-công-ty-cổ-phần-dệt-may-hòa-thọ' AS slug UNION ALL SELECT 'VN000000HTI2' AS id_no, 'Công ty Cổ phần Đầu tư Phát triển Hạ tầng IDICO' AS name, 'công-ty-cổ-phần-đầu-tư-phát-triển-hạ-tầng-idico' AS slug UNION ALL SELECT 'VN000000HTL6' AS id_no, 'Công ty Cổ phần Kỹ thuật và Ô tô Trường Long' AS name, 'công-ty-cổ-phần-kỹ-thuật-và-ô-tô-trường-long' AS slug UNION ALL SELECT 'VN000000HTN2' AS id_no, 'Công ty Cổ phần Hưng Thịnh Incons' AS name, 'công-ty-cổ-phần-hưng-thịnh-incons' AS slug UNION ALL SELECT 'VN000000HTV5' AS id_no, 'Công ty Cổ phần Logistics Vicem' AS name, 'công-ty-cổ-phần-logistics-vicem' AS slug UNION ALL SELECT 'VN000000HU19' AS id_no, 'Công ty Cổ phần Đầu tư và Xây dựng HUD1' AS name, 'công-ty-cổ-phần-đầu-tư-và-xây-dựng-hud1' AS slug UNION ALL SELECT 'VN000000HUB5' AS id_no, 'Công ty Cổ phần Xây lắp Thừa Thiên Huế' AS name, 'công-ty-cổ-phần-xây-lắp-thừa-thiên-huế' AS slug UNION ALL SELECT 'VN000000HVH0' AS id_no, 'Công ty Cổ phần Đầu tư và Công nghệ HVC' AS name, 'công-ty-cổ-phần-đầu-tư-và-công-nghệ-hvc' AS slug UNION ALL SELECT 'VN000000HVN8' AS id_no, 'Tổng Công ty Hàng không Việt Nam - CTCP' AS name, 'tổng-công-ty-hàng-không-việt-nam---ctcp' AS slug UNION ALL SELECT 'VN000000ICT3' AS id_no, 'Công ty Cổ phần Viễn thông - Tin học Bưu điện' AS name, 'công-ty-cổ-phần-viễn-thông---tin-học-bưu-điện' AS slug UNION ALL SELECT 'VN000000IDI4' AS id_no, 'Công ty Cổ phần Đầu tư và Phát triển Đa Quốc Gia I.D.I' AS name, 'công-ty-cổ-phần-đầu-tư-và-phát-triển-đa-quốc-gia-i.d.i' AS slug UNION ALL SELECT 'VN000000IJC4' AS id_no, 'Công ty Cổ phần Phát triển Hạ tầng Kỹ thuật' AS name, 'công-ty-cổ-phần-phát-triển-hạ-tầng-kỹ-thuật' AS slug UNION ALL SELECT 'VN000000ILB2' AS id_no, 'Công ty Cổ phần ICD Tân Cảng - Long Bình' AS name, 'công-ty-cổ-phần-icd-tân-cảng---long-bình' AS slug UNION ALL SELECT 'VN000000IMP0' AS id_no, 'Công ty Cổ phần Dược phẩm Imexpharm' AS name, 'công-ty-cổ-phần-dược-phẩm-imexpharm' AS slug UNION ALL SELECT 'VN000000ITC3' AS id_no, 'Công ty Cổ phần Đầu tư - Kinh doanh Nhà' AS name, 'công-ty-cổ-phần-đầu-tư---kinh-doanh-nhà' AS slug UNION ALL SELECT 'VN000000ITD1' AS id_no, 'Công ty Cổ phần Công nghệ ITD' AS name, 'công-ty-cổ-phần-công-nghệ-itd' AS slug UNION ALL SELECT 'VN000000JVC7' AS id_no, 'Công ty Cổ phần Đầu tư Y tế - Dược phẩm Việt Nam' AS name, 'công-ty-cổ-phần-đầu-tư-y-tế---dược-phẩm-việt-nam' AS slug UNION ALL SELECT 'VN000000KBC7' AS id_no, 'Tổng Công ty Phát triển Đô Thị Kinh Bắc – Công ty Cổ phần' AS name, 'tổng-công-ty-phát-triển-đô-thị-kinh-bắc-–-công-ty-cổ-phần' AS slug UNION ALL SELECT 'VN000000KDC3' AS id_no, 'Công ty Cổ phần Tập đoàn Kido' AS name, 'công-ty-cổ-phần-tập-đoàn-kido' AS slug
) AS t ON c.id_no = t.id_no
ON DUPLICATE KEY UPDATE
    name = t.name,
    slug = t.slug;
COMMIT;

START TRANSACTION;

