FROM companies c
JOIN (
    SELECT 'VN000000KDH2' AS id_no, 'Công ty Cổ phần Đầu tư và Kinh doanh nhà Khang Điền' AS name, 'công-ty-cổ-phần-đầu-tư-và-kinh-doanh-nhà-khang-điền' AS slug UNION ALL SELECT 'VN000000KHG5' AS id_no, 'Công ty Cổ phần Tập đoàn Khải Hoàn Land' AS name, 'công-ty-cổ-phần-tập-đoàn-khải-hoàn-land' AS slug UNION ALL SELECT 'VN000000KHP6' AS id_no, 'Công ty Cổ phần Điện lực Khánh Hòa' AS name, 'công-ty-cổ-phần-điện-lực-khánh-hòa' AS slug UNION ALL SELECT 'VN000000KLB8' AS id_no, 'Ngân hàng Thương mại Cổ phần Kiên Long' AS name, 'ngân-hàng-thương-mại-cổ-phần-kiên-long' AS slug UNION ALL SELECT 'VN000000KMR2' AS id_no, 'Công ty Cổ phần MIRAE' AS name, 'công-ty-cổ-phần-mirae' AS slug UNION ALL SELECT 'VN000000KOS6' AS id_no, 'Công ty Cổ phần KOSY' AS name, 'công-ty-cổ-phần-kosy' AS slug UNION ALL SELECT 'VN000000KSB3' AS id_no, 'Công ty Cổ phần Khoáng sản và Xây dựng Bình Dương' AS name, 'công-ty-cổ-phần-khoáng-sản-và-xây-dựng-bình-dương' AS slug UNION ALL SELECT 'VN000000L102' AS id_no, 'Công ty Cổ phần Lilama 10' AS name, 'công-ty-cổ-phần-lilama-10' AS slug UNION ALL SELECT 'VN000000LAF0' AS id_no, 'Công ty Cổ phần Chế biến Hàng xuất khẩu Long An' AS name, 'công-ty-cổ-phần-chế-biến-hàng-xuất-khẩu-long-an' AS slug UNION ALL SELECT 'VN000000LBM4' AS id_no, 'Công ty Cổ phần Khoáng sản và Vật liệu Xây dựng Lâm Đồng' AS name, 'công-ty-cổ-phần-khoáng-sản-và-vật-liệu-xây-dựng-lâm-đồng' AS slug UNION ALL SELECT 'VN000000LCG4' AS id_no, 'Công ty Cổ phần Lizen' AS name, 'công-ty-cổ-phần-lizen' AS slug UNION ALL SELECT 'VN000000LDG2' AS id_no, 'Công ty Cổ phần Đầu tư LDG' AS name, 'công-ty-cổ-phần-đầu-tư-ldg' AS slug UNION ALL SELECT 'VN000000LGC4' AS id_no, 'Công ty Cổ phần Đầu tư Cầu Đường CII' AS name, 'công-ty-cổ-phần-đầu-tư-cầu-đường-cii' AS slug UNION ALL SELECT 'VN000000LGL5' AS id_no, 'Công ty Cổ phần Đầu tư và Phát triển Đô thị Long Giang' AS name, 'công-ty-cổ-phần-đầu-tư-và-phát-triển-đô-thị-long-giang' AS slug UNION ALL SELECT 'VN000000LHG3' AS id_no, 'Công ty Cổ phần Lon