INSERT INTO company_translations (company_id, lang_code, name, slug, description)
SELECT c.company_id, 'vi', t.name, t.slug, NULL
FROM companies c
JOIN (
    SELECT 'VN000000NAB5' AS id_no, 'Ngân hàng Thương mại Cổ phần Nam Á' AS name, 'ngân-hàng-thương-mại-cổ-phần-nam-á' AS slug UNION ALL SELECT 'VN000000NAF6' AS id_no, 'Công ty Cổ phần Nafoods Group' AS name, 'công-ty-cổ-phần-nafoods-group' AS slug UNION ALL SELECT 'VN000000NAV3' AS id_no, 'Công ty Cổ phần Nam Việt' AS name, 'công-ty-cổ-phần-nam-việt' AS slug UNION ALL SELECT 'VN000000NBB3' AS id_no, 'Công ty Cổ phần Đầu tư Năm Bảy Bảy' AS name, 'công-ty-cổ-phần-đầu-tư-năm-bảy-bảy' AS slug UNION ALL SELECT 'VN000000NCT3' AS id_no, 'Công ty Cổ phần Dịch vụ Hàng hóa Nội Bài' AS name, 'công-ty-cổ-phần-dịch-vụ-hàng-hóa-nội-bài' AS slug UNION ALL SELECT 'VN000000NHA2' AS id_no, 'Tổng Công ty Đầu tư Phát triển Nhà và Đô thị Nam Hà Nội' AS name, 'tổng-công-ty-đầu-tư-phát-triển-nhà-và-đô-thị-nam-hà-nội' AS slug UNION ALL SELECT 'VN000000NHH7' AS id_no, 'Công ty Cổ phần Nhựa Hà Nội' AS name, 'công-ty-cổ-phần-nhựa-hà-nội' AS slug UNION ALL SELECT 'VN000000NHT2' AS id_no, 'Công ty Cổ phần Sản xuất và Thương mại Nam Hoa' AS name, 'công-ty-cổ-phần-sản-xuất-và-thương-mại-nam-hoa' AS slug UNION ALL SELECT 'VN000000NKG3' AS id_no, 'Công ty Cổ phần Thép Nam Kim' AS name, 'công-ty-cổ-phần-thép-nam-kim' AS slug UNION ALL SELECT 'VN000000NLG1' AS id_no, 'Công ty Cổ phần Đầu tư Nam Long' AS name, 'công-ty-cổ-phần-đầu-tư-nam-long' AS slug UNION ALL SELECT 'VN000000NNC6' AS id_no, 'Công ty Cổ phần Đá Núi Nhỏ' AS name, 'công-ty-cổ-phần-đá-núi-nhỏ' AS slug UNION ALL SELECT 'VN000000NO19' AS id_no, 'Công ty Cổ phần Tập đoàn 911' AS name, 'công-ty-cổ-phần-tập-đoàn-911' AS slug UNION ALL SELECT 'VN000000NSC5' AS id_no, 'Công ty Cổ phần Tập đoàn Giống cây trồng Việt Nam' AS name, 'công-ty-cổ-phần-tập-đoàn-giống-cây-trồng-việt-nam' AS slug UNION ALL SELECT 'VN000000NT22' AS id_no, 'Công ty Cổ phần Điện lực Dầu khí Nhơn Trạch 2' AS name, 'công-ty-cổ-phần-điện-lực-dầu-khí-nhơn-trạch-2' AS slug UNION ALL SELECT 'VN000000NTC3' AS id_no, 'Công ty Cổ phần Khu công Nghiệp Nam Tân Uyên' AS name, 'công-ty-cổ-phần-khu-công-nghiệp-nam-tân-uyên' AS slug UNION ALL SELECT 'VN000000NTL4' AS id_no, 'Công ty Cổ phần Phát triển Đô thị Từ Liêm' AS name, 'công-ty-cổ-phần-phát-triển-đô-thị-từ-liêm' AS slug UNION ALL SELECT 'VN000000NVL0' AS id_no, 'Công ty Cổ phần Tập đoàn Đầu tư Địa ốc No Va' AS name, 'công-ty-cổ-phần-tập-đoàn-đầu-tư-địa-ốc-no-va' AS slug UNION ALL SELECT 'VN000000NVT3' AS id_no, 'Công ty Cổ phần Bất động sản Du lịch Ninh Vân Bay' AS name, 'công-ty-cổ-phần-bất-động-sản-du-lịch-ninh-vân-bay' AS slug UNION ALL SELECT 'VN000000OCB9' AS id_no, 'Ngân hàng Thương mại Cổ phần Phương Đông' AS name, 'ngân-hàng-thương-mại-cổ-phần-phương-đông' AS slug UNION ALL SELECT 'VN000000OGC8' AS id_no, 'Công ty Cổ phần Tập đoàn Đại Dương' AS name, 'công-ty-cổ-phần-tập-đoàn-đại-dương' AS slug UNION ALL SELECT 'VN000000OPC9' AS id_no, 'Công ty Cổ phần Dược phẩm OPC' AS name, 'công-ty-cổ-phần-dược-phẩm-opc' AS slug UNION ALL SELECT 'VN000000ORS1' AS id_no, 'Công ty Cổ phần Chứng khoán Tiên Phong' AS name, 'công-ty-cổ-phần-chứng-khoán-tiên-phong' AS slug UNION ALL SELECT 'VN000000PAC8' AS id_no, 'Công ty Cổ phần Pin Ắc quy miền Nam' AS name, 'công-ty-cổ-phần-pin-ắc-quy-miền-nam' AS slug UNION ALL SELECT 'VN000000PAN5' AS id_no, 'Công ty Cổ phần Tập đoàn PAN' AS name, 'công-ty-cổ-phần-tập-đoàn-pan' AS slug UNION ALL SELECT 'VN000000PC11' AS id_no, 'Công ty Cổ phần Tập đoàn PC1' AS name, 'công-ty-cổ-phần-tập-đoàn-pc1' AS slug UNION ALL SELECT 'VN000000PDN9' AS id_no, 'Công ty Cổ phần Cảng Đồng Nai' AS name, 'công-ty-cổ-phần-cảng-đồng-nai' AS slug UNION ALL SELECT 'VN000000PDR0' AS id_no, 'Công ty Cổ phần Phát triển Bất động sản Phát Đạt' AS name, 'công-ty-cổ-phần-phát-triển-bất-động-sản-phát-đạt' AS slug UNION ALL SELECT 'VN000000PDV2' AS id_no, 'Công ty Cổ phần Vận tải và Tiếp vận Phương Đông Việt' AS name, 'công-ty-cổ-phần-vận-tải-và-tiếp-vận-phương-đông-việt' AS slug UNION ALL SELECT 'VN000000PET4' AS id_no, 'Tổng Công ty Cổ phần Dịch vụ Tổng hợp Dầu khí' AS name, 'tổng-công-ty-cổ-phần-dịch-vụ-tổng-hợp-dầu-khí' AS slug UNION ALL SELECT 'VN000000PGC5' AS id_no, 'Tổng Công ty Gas Petrolimex - Công ty Cổ phần' AS name, 'tổng-công-ty-gas-petrolimex---công-ty-cổ-phần' AS slug
) AS t ON c.id_no = t.id_no
ON DUPLICATE KEY UPDATE
