INSERT INTO company_translations (company_id, lang_code, name, slug, description)
SELECT c.company_id, 'vi', t.name, t.slug, NULL
FROM companies c
JOIN (
    SELECT 'VN000000VPX0' AS id_no, 'Công ty Cổ phần Chứng khoán VPBank' AS name, 'công-ty-cổ-phần-chứng-khoán-vpbank' AS slug UNION ALL SELECT 'VN000000VRC0' AS id_no, 'Công ty Cổ phần Bất động sản và Đầu tư VRC' AS name, 'công-ty-cổ-phần-bất-động-sản-và-đầu-tư-vrc' AS slug UNION ALL SELECT 'VN000000VRE6' AS id_no, 'Công ty Cổ phần Vincom Retail' AS name, 'công-ty-cổ-phần-vincom-retail' AS slug UNION ALL SELECT 'VN000000VSC8' AS id_no, 'Công ty Cổ phần Container Việt Nam' AS name, 'công-ty-cổ-phần-container-việt-nam' AS slug UNION ALL SELECT 'VN000000VSH7' AS id_no, 'Công ty Cổ phần Thủy điện Vĩnh Sơn - Sông Hinh' AS name, 'công-ty-cổ-phần-thủy-điện-vĩnh-sơn---sông-hinh' AS slug UNION ALL SELECT 'VN000000VSI5' AS id_no, 'Công ty Cổ phần Đầu tư và Xây dựng Cấp thoát nước' AS name, 'công-ty-cổ-phần-đầu-tư-và-xây-dựng-cấp-thoát-nước' AS slug UNION ALL SELECT 'VN000000VTB8' AS id_no, 'Công ty Cổ phần Viettronics Tân Bình' AS name, 'công-ty-cổ-phần-viettronics-tân-bình' AS slug UNION ALL SELECT 'VN000000VTO1' AS id_no, 'Công ty Cổ phần Vận tải Xăng dầu VITACO' AS name, 'công-ty-cổ-phần-vận-tải-xăng-dầu-vitaco' AS slug UNION ALL SELECT 'VN000000VTP8' AS id_no, 'Tổng Công ty Cổ phần Bưu chính Viettel' AS name, 'tổng-công-ty-cổ-phần-bưu-chính-viettel' AS slug UNION ALL SELECT 'VN000000VVS8' AS id_no, 'Công ty Cổ phần Đầu tư Phát triển máy Việt Nam' AS name, 'công-ty-cổ-phần-đầu-tư-phát-triển-máy-việt-nam' AS slug UNION ALL SELECT 'VN000000YBM7' AS id_no, 'Công ty Cổ phần YBM' AS name, 'công-ty-cổ-phần-ybm' AS slug UNION ALL SELECT 'VN000000YEG3' AS id_no, 'Công ty Cổ phần Tập đoàn Yeah1' AS name, 'công-ty-cổ-phần-tập-đoàn-yeah1' AS slug
) AS t ON c.id_no = t.id_no
ON DUPLICATE KEY UPDATE
    name = t.name,
    slug = t.slug;
COMMIT;

